for nm, f in (("mean (sd)", lambda x: f"{x.mean():.3f} ({x.std():.3f})"), ("min / max", lambda x: f"{x.min():.3f} / {x.max():.3f}"), ("median", lambda x: f"{x.median():.3f}"), ("90th percentile", lambda x: f"{x.quantile(.9):.3f}"), ("99th percentile", lambda x: f"{x.quantile(.99):.3f}")):
    w(f"| {nm} | {f(base.r2)} | {f(base.rmse)} | {f(base.mae)} |")
w(f"| SI | 0.41 | 67 | 47 |")
w()
w(f"**Fraction of runs with R2 >= 0.41: {(base.r2 >= .41).sum()}/{len(base)}** (one-sided 95% upper bound for the probability of such a run: {100 * ub:.1f}%). The SI value lies {(0.41 - base.r2.mean()) / base.r2.std():.1f} sd above the mean of the 50 runs and {0.41 - base.r2.max():.3f} above the best run. **Run-to-run (seed) variation does not explain the gap.**")
